def reverse_pairs(nums):
    def sort(a):
        if len(a) <= 1:
            return a, 0
        mid = len(a) // 2
        l, x = sort(a[:mid])
        r, y = sort(a[mid:])
        cnt = x + y
        j = 0
        for v in l:
            while j < len(r) and v > 2 * r[j]:
                j += 1
            cnt += j
        return sorted(l + r), cnt
    return sort(nums)[1]
